-- Black Sword Ultimate — Neon Postgres, Auth and Data API schema.
-- GENERATED by scripts/build-neon-schema.mjs. Do not edit by hand.
-- Includes every application migration through player-to-player trading (v20).
-- Neon Auth identities live in neon_auth; Supabase realtime publications are
-- intentionally replaced by the authenticated polling client in neon-game-client.js.


-- ============================================================================
-- Neon compatibility bootstrap (generated)
-- ============================================================================
do $neon_roles$
begin
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then
    create role authenticated nologin;
  end if;
  if not exists (select 1 from pg_roles where rolname = 'anonymous') then
    create role anonymous nologin;
  end if;
end
$neon_roles$;

create or replace function public.neon_subject_uuid(subject text)
returns uuid
language plpgsql
immutable
as $neon_subject_uuid$
begin
  if subject is null or subject = '' then
    return null;
  end if;
  if subject ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    return subject::uuid;
  end if;
  return (substr(md5(subject), 1, 8) || '-' || substr(md5(subject), 9, 4) || '-' ||
          substr(md5(subject), 13, 4) || '-' || substr(md5(subject), 17, 4) || '-' ||
          substr(md5(subject), 21, 12))::uuid;
end;
$neon_subject_uuid$;

create schema if not exists auth;

create or replace function auth.jwt()
returns jsonb
language sql
stable
as $auth_jwt$
  select coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb
$auth_jwt$;

create or replace function auth.role()
returns text
language sql
stable
as $auth_role$
  select coalesce(nullif(auth.jwt() ->> 'role', ''),
                  nullif(current_setting('request.jwt.claim.role', true), ''),
                  current_user)
$auth_role$;

create or replace function auth.uid()
returns uuid
language sql
stable
as $auth_uid$
  select public.neon_subject_uuid(nullif(auth.jwt() ->> 'sub', ''))
$auth_uid$;

grant usage on schema auth to authenticated, anonymous;
grant execute on function auth.uid(), auth.role(), auth.jwt() to authenticated, anonymous;
grant execute on function public.neon_subject_uuid(text) to authenticated, anonymous;
grant usage on schema public to authenticated, anonymous;


-- Source: supabase/schema.sql
-- Black Sword Ultimate multiplayer schema
-- Run once in Supabase Dashboard -> SQL Editor -> New query.
-- Safe to run again: tables and policies are created idempotently where possible.

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

create table if not exists public.profiles (
  id uuid primary key,
  player_code text not null unique,
  display_name text not null default 'Wandering Hero',
  level integer not null default 1 check (level between 1 and 999),
  current_location text not null default 'Kaliwasch City',
  last_seen timestamptz not null default now(),
  created_at timestamptz not null default now()
);

create table if not exists public.game_saves (
  user_id uuid primary key,
  save_data jsonb not null default '{}'::jsonb,
  updated_at timestamptz not null default now()
);

create table if not exists public.friend_requests (
  id uuid primary key default gen_random_uuid(),
  sender_id uuid not null references public.profiles(id) on delete cascade,
  receiver_id uuid not null references public.profiles(id) on delete cascade,
  status text not null default 'pending' check (status in ('pending','accepted','rejected')),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  check (sender_id <> receiver_id)
);
create unique index if not exists one_pending_friend_request
  on public.friend_requests (least(sender_id, receiver_id), greatest(sender_id, receiver_id))
  where status in ('pending','accepted');

create table if not exists public.messages (
  id bigint generated by default as identity primary key,
  sender_id uuid not null references public.profiles(id) on delete cascade,
  receiver_id uuid references public.profiles(id) on delete cascade,
  body text not null check (char_length(body) between 1 and 300),
  created_at timestamptz not null default now(),
  expires_at timestamptz not null default(now()+interval '5 minutes'),
  constraint messages_five_minute_expiration check(expires_at=created_at+interval '5 minutes')
);
create index if not exists messages_created_idx on public.messages(created_at desc);
create index if not exists messages_receiver_idx on public.messages(receiver_id, created_at desc);

create table if not exists public.guilds (
  id uuid primary key default gen_random_uuid(),
  name text not null unique check (char_length(name) between 3 and 32),
  owner_id uuid not null references public.profiles(id) on delete cascade,
  rupees bigint not null default 0 check (rupees >= 0),
  created_at timestamptz not null default now()
);

create table if not exists public.guild_members (
  guild_id uuid not null references public.guilds(id) on delete cascade,
  user_id uuid not null references public.profiles(id) on delete cascade,
  role text not null default 'member' check (role in ('owner','officer','member')),
  joined_at timestamptz not null default now(),
  primary key (guild_id, user_id)
);

create table if not exists public.blocks (
  blocker_id uuid not null references public.profiles(id) on delete cascade,
  blocked_id uuid not null references public.profiles(id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (blocker_id, blocked_id),
  check (blocker_id <> blocked_id)
);

create table if not exists public.reports (
  id uuid primary key default gen_random_uuid(),
  reporter_id uuid not null references public.profiles(id) on delete cascade,
  reported_id uuid not null references public.profiles(id) on delete cascade,
  reason text not null check (char_length(reason) between 3 and 500),
  created_at timestamptz not null default now(),
  check (reporter_id <> reported_id)
);

-- Creates the permanent readable ID when Auth creates a guest or linked account.
create or replace function public.create_player_profile()
returns trigger
language plpgsql
security definer set search_path = public
as $$
declare
  generated_code text;
begin
  loop
    generated_code := 'KND-' || substring(upper(replace(gen_random_uuid()::text, '-', '')) from 1 for 4)
                            || '-' || substring(upper(replace(gen_random_uuid()::text, '-', '')) from 1 for 4);
    exit when not exists (select 1 from public.profiles where player_code = generated_code);
  end loop;
  insert into public.profiles (id, player_code, display_name)
  values (public.neon_subject_uuid(new.id::text), generated_code, coalesce(nullif(new.name,''), 'Wandering Hero'))
  on conflict (id) do nothing;
  return new;
end;
$$;

drop trigger if exists create_profile_after_signup on neon_auth."user";
create trigger create_profile_after_signup
after insert on neon_auth."user"
for each row execute function public.create_player_profile();

-- True only after an anonymous account is linked to Google or another provider.
create or replace function public.has_linked_identity()
returns boolean
language sql stable security definer set search_path = public
as $$
  select exists (
    select 1 from neon_auth.account
    where "userId"::text = coalesce(auth.jwt() ->> 'sub', '') and "providerId" <> 'credential'
  );
$$;
grant execute on function public.has_linked_identity() to authenticated;

alter table public.profiles enable row level security;
alter table public.game_saves enable row level security;
alter table public.friend_requests enable row level security;
alter table public.messages enable row level security;
alter table public.guilds enable row level security;
alter table public.guild_members enable row level security;
alter table public.blocks enable row level security;
alter table public.reports enable row level security;

-- Recreate named policies so rerunning this file updates security rules.
do $$ declare p record; begin
  for p in select schemaname, tablename, policyname from pg_policies
           where schemaname='public' and tablename in
           ('profiles','game_saves','friend_requests','messages','guilds','guild_members','blocks','reports')
  loop execute format('drop policy if exists %I on %I.%I', p.policyname, p.schemaname, p.tablename); end loop;
end $$;

