-- v13 globally unique hero names and real system voice descriptors.
create table if not exists public.hero_name_registry (
 id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id) on delete cascade,
 hero_slot text not null,hero_name text not null check(char_length(trim(hero_name)) between 2 and 20),
 normalized_name text generated always as (lower(trim(hero_name))) stored,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(owner_id,hero_slot),unique(normalized_name)
);
insert into public.hero_name_registry(owner_id,hero_slot,hero_name)
select p.id,'legacy-profile',left(trim(p.display_name),20) from public.profiles p where char_length(trim(p.display_name)) between 2 and 20
on conflict do nothing;
alter table public.hero_name_registry enable row level security;
drop policy if exists hero_names_owner_read on public.hero_name_registry;
drop policy if exists hero_names_owner_read on public.hero_name_registry;
create policy hero_names_owner_read on public.hero_name_registry for select to authenticated using(owner_id=auth.uid());
revoke all on public.hero_name_registry from anonymous,authenticated;grant select on public.hero_name_registry to authenticated;

create or replace function public.hero_name_available(desired_name text,current_slot text default null)
returns boolean language sql stable security definer set search_path=public as $$
 select not exists(select 1 from hero_name_registry where normalized_name=lower(trim(desired_name)) and not(owner_id=auth.uid() and hero_slot=coalesce(current_slot,'')));
$$;
create or replace function public.reserve_hero_name(desired_name text,target_slot text)
returns boolean language plpgsql security definer set search_path=public as $$begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if char_length(trim(desired_name))<2 or char_length(trim(desired_name))>20 then raise exception 'Hero name must contain 2 to 20 characters';end if;
 if exists(select 1 from hero_name_registry where normalized_name=lower(trim(desired_name)) and not(owner_id=auth.uid() and hero_slot=target_slot)) then raise exception 'The name already exists. Please choose another name.' using errcode='unique_violation';end if;
 insert into hero_name_registry(owner_id,hero_slot,hero_name,updated_at) values(auth.uid(),target_slot,trim(desired_name),now())
 on conflict(owner_id,hero_slot) do update set hero_name=excluded.hero_name,updated_at=now();return true;
exception when unique_violation then raise exception 'The name already exists. Please choose another name.';end$$;
create or replace function public.release_hero_name(target_slot text)
returns boolean language plpgsql security definer set search_path=public as $$begin delete from hero_name_registry where owner_id=auth.uid() and hero_slot=target_slot;return found;end$$;
grant execute on function public.hero_name_available(text,text) to authenticated;grant execute on function public.reserve_hero_name(text,text) to authenticated;grant execute on function public.release_hero_name(text) to authenticated;

-- Voice IDs now hold a system voice descriptor such as system:Microsoft Ravi.
alter table public.messages drop constraint if exists messages_voice_id_check;
alter table public.chat_room_messages drop constraint if exists chat_room_messages_voice_id_check;
alter table public.messages alter column voice_id type text,alter column voice_id set default 'system:default';
alter table public.chat_room_messages alter column voice_id type text,alter column voice_id set default 'system:default';
alter table public.messages drop constraint if exists messages_voice_id_length;
alter table public.chat_room_messages drop constraint if exists chat_room_messages_voice_id_length;
alter table public.messages add constraint messages_voice_id_length check(char_length(voice_id) between 2 and 180) not valid;
alter table public.chat_room_messages add constraint chat_room_messages_voice_id_length check(char_length(voice_id) between 2 and 180) not valid;

-- v14 public dropped items expire after one hour.
alter table public.world_drops alter column expires_at set default(now()+interval '1 hour');
update public.world_drops set expires_at=least(expires_at,created_at+interval '1 hour') where expires_at>created_at+interval '1 hour';

-- v15 prevent false duplicate-name errors when an existing hero continues.
create or replace function public.reserve_hero_name(desired_name text,target_slot text)
returns boolean language plpgsql security definer set search_path=public as $$declare existing hero_name_registry%rowtype;begin
 if auth.uid() is null then raise exception 'Authentication required';end if;
 if char_length(trim(desired_name))<2 or char_length(trim(desired_name))>20 then raise exception 'Hero name must contain 2 to 20 characters';end if;
 select * into existing from hero_name_registry where normalized_name=lower(trim(desired_name));
 if existing.id is not null and existing.owner_id=auth.uid() and existing.hero_slot='legacy-profile' then delete from hero_name_registry where id=existing.id;existing.id=null;end if;
 if existing.id is not null and not(existing.owner_id=auth.uid() and existing.hero_slot=target_slot) then raise exception 'The name already exists. Please choose another name.';end if;
 insert into hero_name_registry(owner_id,hero_slot,hero_name,updated_at) values(auth.uid(),target_slot,trim(desired_name),now())
 on conflict(owner_id,hero_slot) do update set hero_name=excluded.hero_name,updated_at=now();return true;
exception when unique_violation then raise exception 'The name already exists. Please choose another name.';end$$;
grant execute on function public.reserve_hero_name(text,text) to authenticated;

-- v16 generic realtime sessions for accessible board/card games.
create table if not exists public.game_hall_sessions (
 id uuid primary key default gen_random_uuid(),game_type text not null check(game_type in ('ludo','snakes','chess','carrom','blackjack')),
 name text not null,owner_id uuid not null references profiles(id) on delete cascade,max_players integer not null check(max_players between 1 and 5),
 state jsonb not null default '{}'::jsonb,version integer not null default 0,status text not null default 'waiting' check(status in ('waiting','playing','finished')),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.game_hall_members(session_id uuid not null references game_hall_sessions(id) on delete cascade,user_id uuid not null references profiles(id) on delete cascade,seat integer not null,joined_at timestamptz not null default now(),primary key(session_id,user_id),unique(session_id,seat));
create table if not exists public.game_hall_invites(id uuid primary key default gen_random_uuid(),session_id uuid not null references game_hall_sessions(id) on delete cascade,sender_id uuid not null references profiles(id) on delete cascade,receiver_id uuid not null references profiles(id) on delete cascade,status text not null default 'pending' check(status in ('pending','accepted','rejected')),created_at timestamptz not null default now(),unique(session_id,receiver_id));
alter table game_hall_sessions enable row level security;alter table game_hall_members enable row level security;alter table game_hall_invites enable row level security;
do $$declare p record;begin for p in select schemaname,tablename,policyname from pg_policies where schemaname='public' and tablename in ('game_hall_sessions','game_hall_members','game_hall_invites') loop execute format('drop policy if exists %I on %I.%I',p.policyname,p.schemaname,p.tablename);end loop;end$$;
create or replace function public.game_session_member(s uuid)returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from game_hall_members where session_id=s and user_id=auth.uid());$$;grant execute on function game_session_member(uuid) to authenticated;
drop policy if exists sessions_read on game_hall_sessions;
create policy sessions_read on game_hall_sessions for select to authenticated using(owner_id=auth.uid() or game_session_member(id) or status='waiting');drop policy if exists sessions_owner_delete on game_hall_sessions;
create policy sessions_owner_delete on game_hall_sessions for delete to authenticated using(owner_id=auth.uid());
drop policy if exists members_read on game_hall_members;
create policy members_read on game_hall_members for select to authenticated using(game_session_member(session_id) or exists(select 1 from game_hall_sessions s where s.id=session_id and s.status='waiting'));
drop policy if exists invites_read on game_hall_invites;
create policy invites_read on game_hall_invites for select to authenticated using(sender_id=auth.uid() or receiver_id=auth.uid());drop policy if exists invites_send on game_hall_invites;
create policy invites_send on game_hall_invites for insert to authenticated with check(sender_id=auth.uid() and exists(select 1 from game_hall_sessions s where s.id=session_id and s.owner_id=auth.uid()));drop policy if exists invites_update on game_hall_invites;
create policy invites_update on game_hall_invites for update to authenticated using(receiver_id=auth.uid()) with check(receiver_id=auth.uid());
grant select,delete on game_hall_sessions to authenticated;grant select on game_hall_members to authenticated;grant select,insert,update on game_hall_invites to authenticated;
create or replace function public.create_game_hall_session(kind text,session_name text,players integer,initial_state jsonb)
returns uuid language plpgsql security definer set search_path=public as $$declare sid uuid;begin if not has_linked_identity() then raise exception 'Link Google before creating an online game';end if;insert into game_hall_sessions(game_type,name,owner_id,max_players,state) values(kind,left(session_name,60),auth.uid(),greatest(1,least(5,players)),initial_state) returning id into sid;insert into game_hall_members values(sid,auth.uid(),0,now());return sid;end$$;
create or replace function public.join_game_hall_session(sid uuid)
returns integer language plpgsql security definer set search_path=public as $$declare s game_hall_sessions%rowtype;seat_no integer;begin select * into s from game_hall_sessions where id=sid;if s.id is null then raise exception 'Game not found';end if;if s.status<>'waiting' then raise exception 'Game already started';end if;if s.owner_id<>auth.uid() and not exists(select 1 from game_hall_invites where session_id=sid and receiver_id=auth.uid() and status='accepted') then raise exception 'Invitation required';end if;select coalesce(min(x),0) into seat_no from generate_series(0,s.max_players-1)x where not exists(select 1 from game_hall_members m where m.session_id=sid and m.seat=x);if seat_no is null then raise exception 'Game is full';end if;insert into game_hall_members values(sid,auth.uid(),seat_no,now()) on conflict(session_id,user_id) do nothing;return seat_no;end$$;
create or replace function public.update_game_hall_state(sid uuid,expected_version integer,new_state jsonb,new_status text default 'playing')
returns integer language plpgsql security definer set search_path=public as $$declare next_version integer;begin if not game_session_member(sid) then raise exception 'Not a game member';end if;update game_hall_sessions set state=new_state,version=version+1,status=new_status,updated_at=now() where id=sid and version=expected_version returning version into next_version;if next_version is null then raise exception 'Game state changed; refresh and retry';end if;return next_version;end$$;
grant execute on function create_game_hall_session(text,text,integer,jsonb) to authenticated;grant execute on function join_game_hall_session(uuid) to authenticated;grant execute on function update_game_hall_state(uuid,integer,jsonb,text) to authenticated;


